// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);

        Recorder rec = new Recorder(from, tos[0], v);

        try c.transfer(from, address(rec), tos, v) returns (bool ok) {
            assertTrue(!ok || rec.delivered(), "transfer must deliver the call for tos[0]");
        } catch {
            assertTrue(false, "transfer reverted unexpectedly");
        }
    }
}

contract Recorder {
    bool private _delivered;
    bytes32 private _expected;

    constructor(address from, address to, uint256 v) {
        _expected = keccak256(abi.encodePacked(bytes4(keccak256("transferFrom(address,address,uint256)")), from, to, v));
    }

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (keccak256(abi.encodePacked(msg.sig, from, to, v)) == _expected) {
            _delivered = true;
        }
        return true;
    }

    function delivered() external view returns (bool) {
        return _delivered;
    }
}
